<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import supportAtlas from '../assets/cast-support-s11.png'
import passageDeck from '../assets/deck-passage-s13.png'
import looseStraw from '../assets/loose-straw-s13.png'
import {newTask,mergeTaskDraft,FEEDBACK_TEXT,moveObstacle,verifyPassage,pointSide,addSideHelp,markHeard,setTaskResponse,taskComplete,taskPayload,sideDescription,clipCaption,soundPlan,TASK_IDS,type ShipTask,type ShipTaskContext,type ShipTaskState,type TaskSide,type ClipId} from '../shipTasks'
const props=defineProps<{task:ShipTask;context:ShipTaskContext&{reducedMotion?:boolean};busy?:boolean;error?:string}>()
type Payload=ReturnType<typeof taskPayload>&{task_id:string}
const emit=defineEmits<{complete:[payload:Payload];progress:[payload:Payload];close:[payload:Payload]}>()
const state=ref<ShipTaskState>(newTask(props.task,props.context.recordId??crypto.randomUUID()))
const dragOffset=ref({x:0,y:0})
const selected=ref(false),walking=ref(false),notice=ref(''),playing=ref<ClipId|''>(''),soundError=ref('')
const panel=ref<HTMLElement>(),storageZone=ref<HTMLElement>(),requestedComplete=ref(false),conflictText=ref('')
let walkTimer=0,audioTimer=0,run=0,disposed=false,audio:AudioContext|undefined
let sources:AudioScheduledSourceNode[]=[]
let pointer:{id:number;x:number;y:number;target:HTMLElement}|null=null
const identity=computed(()=>[props.task,props.context.routeId,props.context.nodeId,props.context.actorId].join(':'))
const cacheKey=computed(()=>`caocuan:s11:ship-task:v1:${identity.value}`)
const title=computed(()=>props.task==='passage'?'给韩伯留条路':props.task==='side'?'哪一舷朝向曹营？':'听清江上的变化')
const canFinish=computed(()=>taskComplete(state.value)&&!walking.value&&!playing.value&&!props.busy)
const chosen=computed(()=>state.value.attempts.at(-1)?.side)
const clips:ClipId[]=['arrow_change','shore_report']
function at(){return new Date().toISOString()}
function trapTab(event:KeyboardEvent){if(event.key!=='Tab'||!panel.value)return;const targets=Array.from(panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')).filter(target=>target.getClientRects().length>0);const first=targets[0],last=targets.at(-1);if(!first){event.preventDefault();return}if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onMounted(()=>{void nextTick(()=>panel.value?.focus?.())})
function payload(status:'draft'|'complete'='draft'):Payload{return{task_id:TASK_IDS[props.task],...taskPayload(state.value,status)}}
function cache(){try{localStorage.setItem(cacheKey.value,JSON.stringify(state.value))}catch{}}
function progress(){cache();emit('progress',payload(requestedComplete.value?'complete':'draft'))}
function rememberConflict(text:string){if(!text)return;conflictText.value=text;try{localStorage.setItem(`${cacheKey.value}:conflict`,text)}catch{}}
function cachedState():ShipTaskState|null{try{const raw=localStorage.getItem(cacheKey.value);if(!raw)return null;const saved=JSON.parse(raw);return saved.task===props.task&&typeof saved.id==='string'&&Array.isArray(saved.attempts)&&Array.isArray(saved.feedback)&&Array.isArray(saved.heard)&&Array.isArray(saved.placements)&&Number.isInteger(saved.sequence)?saved:null}catch{return null}}
function restore(){
 stopSound();clearTimeout(walkTimer);walking.value=false;selected.value=false;notice.value='';soundError.value='';conflictText.value=''
 try{conflictText.value=localStorage.getItem(`${cacheKey.value}:conflict`)??''}catch{}
 const restored=mergeTaskDraft(props.task,props.context.recordId??crypto.randomUUID(),props.context.initialPayload,cachedState())
 state.value=restored.state;requestedComplete.value=props.context.initialPayload?.status==='complete';rememberConflict(restored.conflictText);cache()
}
watch(identity,restore,{immediate:true})
watch(()=>props.context.initialPayload,value=>{if(!value)return;const restored=mergeTaskDraft(props.task,props.context.recordId??state.value.id,value,state.value);state.value=restored.state;requestedComplete.value=value.status==='complete'||requestedComplete.value;rememberConflict(restored.conflictText);cache()})
function recoverText(){if(props.busy||props.context.initialPayload?.status==='complete')return;state.value=setTaskResponse(state.value,conflictText.value);conflictText.value='';try{localStorage.removeItem(`${cacheKey.value}:conflict`)}catch{};cache()}
function move(){if(props.busy||walking.value)return;const next=moveObstacle(state.value,'right_rack',at());if(next===state.value)return;state.value=next;selected.value=false;notice.value='散草收在右舷边，舱中这条路空出来了。';progress()}
function selectObstacle(){if(!props.busy&&!walking.value&&state.value.obstacle==='passage')selected.value=true}
function cancelPointer(){const old=pointer;pointer=null;dragOffset.value={x:0,y:0};if(old)try{old.target.releasePointerCapture(old.id)}catch{}}
function pointerStart(event:PointerEvent){if(props.busy||walking.value||state.value.obstacle!=='passage'||(event.button!==undefined&&event.button!==0))return;cancelPointer();selected.value=true;const target=event.currentTarget as HTMLElement;pointer={id:event.pointerId,x:event.clientX,y:event.clientY,target};try{target.setPointerCapture(event.pointerId)}catch{}}
function pointerMove(event:PointerEvent){if(pointer&&pointer.id===event.pointerId)dragOffset.value={x:event.clientX-pointer.x,y:event.clientY-pointer.y}}
function pointerUp(event:PointerEvent){const old=pointer;if(!old||old.id!==event.pointerId)return;const r=storageZone.value?.getBoundingClientRect();const dragged=Math.hypot(event.clientX-old.x,event.clientY-old.y)>4;cancelPointer();if(!props.busy&&dragged&&r&&event.clientX>=r.left&&event.clientX<=r.right&&event.clientY>=r.top&&event.clientY<=r.bottom)move()}
async function walk(){if(props.busy||walking.value||state.value.obstacle!=='right_rack'||state.value.walked)return;walking.value=true;notice.value='让我试试能不能过去。';await new Promise<void>(resolve=>{walkTimer=window.setTimeout(resolve,props.context.reducedMotion?0:1600)});if(disposed||!walking.value)return;state.value=verifyPassage(state.value,at());walking.value=false;notice.value='走得过去了。舱中别再堆草，我来系牢。';progress()}
function point(side:TaskSide){if(props.busy)return;state.value=pointSide(state.value,side,props.context,at());notice.value=`${sideDescription(side,props.context)}${side===props.context.currentSide?'再看看另一边？':''}`;progress()}
function ask(){if(props.busy)return;state.value=addSideHelp(state.value,'LOOK_EMPTY_SIDE',at());notice.value=FEEDBACK_TEXT.LOOK_EMPTY_SIDE;progress()}
function finish(){if(!canFinish.value)return;requestedComplete.value=true;cache();emit('complete',payload('complete'))}
function leave(){if(props.busy)return;cancelPointer();walking.value=false;clearTimeout(walkTimer);stopSound();progress();emit('close',payload(requestedComplete.value?'complete':'draft'))}
function editResponse(event:Event){if(props.busy)return;state.value=setTaskResponse(state.value,(event.target as HTMLTextAreaElement).value);cache()}
function stopSound(){run++;clearTimeout(audioTimer);for(const source of sources)try{source.stop()}catch{}sources=[];playing.value=''}
function readClip(clip:ClipId){if(props.busy)return;stopSound();state.value=markHeard(state.value,clip,'text_equivalent',at());notice.value=clipCaption(clip,props.context);progress()}
async function playClip(clip:ClipId){
 if(props.busy)return;stopSound();soundError.value='';const ticket=run;const plan=soundPlan(clip,props.context)
 try{
  const Constructor=window.AudioContext??(window as unknown as {webkitAudioContext?:typeof AudioContext}).webkitAudioContext
  if(!Constructor)throw Error('no-audio')
  audio??=new Constructor();await audio.resume();if(ticket!==run||disposed)return
  playing.value=clip;const begin=audio.currentTime+.035
  for(const segment of plan.segments){
   const gain=audio.createGain();gain.gain.setValueAtTime(.0001,begin+segment.at);gain.gain.exponentialRampToValueAtTime(segment.gain,begin+segment.at+.035);gain.gain.exponentialRampToValueAtTime(.0001,begin+segment.at+segment.duration);gain.connect(audio.destination)
   if(segment.kind==='call'){
    const oscillator=audio.createOscillator(),filter=audio.createBiquadFilter();oscillator.type='sawtooth';oscillator.frequency.setValueAtTime(segment.frequency,begin+segment.at);oscillator.frequency.linearRampToValueAtTime(segment.frequency*.84,begin+segment.at+segment.duration);filter.type='lowpass';filter.frequency.value=900;oscillator.connect(filter);filter.connect(gain);oscillator.onended=()=>{oscillator.disconnect();filter.disconnect();gain.disconnect()};oscillator.start(begin+segment.at);oscillator.stop(begin+segment.at+segment.duration);sources.push(oscillator)
   }else{
    const buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*segment.duration),audio.sampleRate),data=buffer.getChannelData(0);let seed=1937+Math.round(segment.at*1000);for(let i=0;i<data.length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;data[i]=(seed/4294967296)*2-1}
    const source=audio.createBufferSource(),filter=audio.createBiquadFilter();source.buffer=buffer;filter.type=segment.kind==='arrow'?'bandpass':'lowpass';filter.frequency.setValueAtTime(segment.frequency,begin+segment.at);filter.frequency.exponentialRampToValueAtTime(segment.kind==='arrow'?180:90,begin+segment.at+segment.duration);source.connect(filter);filter.connect(gain);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect()};source.start(begin+segment.at);sources.push(source)
   }
  }
  notice.value=clipCaption(clip,props.context)
  audioTimer=window.setTimeout(()=>{if(disposed||ticket!==run)return;playing.value='';sources=[];state.value=markHeard(state.value,clip,'local_web_audio',at());progress()},(plan.duration+.05)*1000)
 }catch{playing.value='';soundError.value='此设备暂时不能发声。可以展开这段文字，仍能按眼前材料说自己的话。'}
}
onBeforeUnmount(()=>{cancelPointer();disposed=true;walking.value=false;clearTimeout(walkTimer);stopSound();cache();void audio?.close()})
</script>

<template>
<section class="ship-task" :class="{'is-reduced':context.reducedMotion,'is-passage-scene':task==='passage'}" role="dialog" aria-modal="true" :aria-label="title" @keydown.stop="trapTab" @keydown.esc.prevent="leave" @pointermove.capture="pointerMove" @pointerup.capture="pointerUp" @pointercancel="cancelPointer">
 <img v-if="task==='passage'" class="ship-task__passage-backdrop" :src="passageDeck" alt="" aria-hidden="true" /><div ref="panel" class="ship-task__frame" tabindex="-1"><header><div><span>{{context.authorName}} · 船边</span><h2>{{title}}</h2></div><button class="ship-task__close" :disabled="busy" aria-label="回到当前场景" @click="leave">×</button></header>
 <p v-if="error" class="ship-task__save-error" role="alert">{{error}} 你的操作和原话仍在，可以重试。</p>
 <p class="ship-task__instruction">{{task==='passage'?'把舱中挡路的散草挪到舷边，再请韩伯试走。':task==='side'?'两边都看一眼，再指给韩伯看。':'点江面和岸楼，重听两处动静，再告诉同伴你最担心什么。'}}</p>
 <div class="ship-task__object-space" :class="`is-${task}`">
  <svg v-if="task==='side'" class="ship-task__deck" viewBox="0 0 760 340" role="img" aria-label="同一条船的两侧：右舷与左舷分别保持原来的装置和留箭">
   <defs><linearGradient id="task-timber" x2="0" y2="1"><stop stop-color="#9d784d"/><stop offset=".5" stop-color="#684c31"/><stop offset="1" stop-color="#302b24"/></linearGradient><pattern id="task-planks" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M0 0H40M0 39H40" stroke="#d7ba7a" stroke-opacity=".18"/><path d="M4 13Q16 8 37 13M9 24Q22 29 34 25" fill="none" stroke="#2c241d" stroke-opacity=".4"/></pattern></defs>
   <path d="M35 170Q93 42 230 44H574Q672 55 730 170Q669 285 574 296H230Q92 296 35 170Z" fill="url(#task-timber)" stroke="#b99f6a" stroke-width="5"/><path d="M58 170Q110 63 230 65H574Q655 78 706 170Q655 265 574 275H230Q112 275 58 170Z" fill="url(#task-planks)" stroke="#2f2b21" stroke-width="4"/>
   <path d="M126 170H632" stroke="#e7d8a4" stroke-width="31" stroke-opacity=".12" stroke-linecap="round"/><path d="M122 170H637" stroke="#d3c594" stroke-width="2" stroke-dasharray="9 10" stroke-opacity=".65"/>
   <text x="375" y="32" text-anchor="middle" fill="#e5d4a7" font-size="16">右舷</text><text x="375" y="326" text-anchor="middle" fill="#e5d4a7" font-size="16">左舷</text>
   <template v-if="task==='side'" v-for="side in (['right','left'] as const)" :key="side"><g v-if="context.layout==='both'||(context.layout==='one'&&side==='right')" :transform="`translate(0 ${side==='right'?0:196})`"><g v-for="i in 6" :key="i" :transform="`translate(${165+i*62} 74)`"><template v-if="context.material==='straw'"><path d="M-16-16L-22 26H22L16-16Z" fill="#b3a476" stroke="#d5c18b"/><path d="M-10-13L-12 21M-4-15V23M4-15V23M10-13L12 21M-20 10H20" stroke="#6e5d37"/></template><template v-else><path d="M0-20V26M-22-4H22" stroke="#aa8055" stroke-width="6"/><path d="M-18-4L-13 20H13L18-4" fill="#647073" stroke="#a2aa9b"/></template><g v-if="(side==='right'?context.first:context.second)>0" stroke="#d8c99b" stroke-width="2"><path d="M-31-31L-4 3M-14-38L6 1M6-37L13 2"/><path d="M-34-28L-29-33M-17-35L-12-40M3-34L9-39" stroke="#e6dfcb" stroke-width="5"/></g></g></g></template>
   
  </svg>
  <template v-if="task==='passage'">
   <div class="ship-task__hanber" :class="{'is-crossing':walking||state.walked}" :style="{backgroundImage:`url(${supportAtlas})`}" role="img" :aria-label="state.walked?'韩伯已通过舱中通路':walking?'韩伯正在通过舱中通路':'韩伯在通道前等候'"></div>
   <button class="ship-task__bundle" :style="{translate:`${dragOffset.x}px ${dragOffset.y}px`}" :class="{'is-racked':state.obstacle==='right_rack','is-selected':selected}" :disabled="busy||walking||state.obstacle!=='passage'" :draggable="false" @click="selectObstacle" @pointerdown.stop="pointerStart" @dragstart.prevent @lostpointercapture="cancelPointer" aria-label="拿起挡路散草"><img :src="looseStraw" alt="" draggable="false" /><span>{{state.obstacle==='passage'?'挡路散草':'已经收好'}}</span></button>
   <button ref="storageZone" class="ship-task__rack" :class="{'is-ready':selected}" :disabled="busy||walking" @click="selected&&move()"><span>舷边束草位</span><small>{{state.obstacle==='right_rack'?'散草已收在这里':selected?'放下手里的散草':'先拿起舱中散草'}}</small></button>
  </template>
  <template v-else-if="task==='side'"><button v-for="side in (['right','left'] as const)" :key="side" class="ship-task__side-target" :class="[`is-${side}`,{'is-pointed':chosen===side}]" :disabled="busy" @click="point(side)"><i></i><span>{{side==='right'?'指出右舷':'指出左舷'}}</span></button></template>
  <template v-else>
   <svg class="ship-task__water" viewBox="0 0 760 340" role="img" aria-label="雾江上的船侧与对岸寨楼，分别对应箭声变化和岸上动静"><path d="M0 220Q140 198 270 220T760 219M0 265Q180 247 360 266T760 260M0 310Q180 295 360 310T760 306" fill="none" stroke="#8ea7a3" stroke-opacity=".25"/><path d="M438 93H760V122H438Z" fill="#465b5a"/><path d="M516 92V48H634V92M533 47V23H616V47" fill="#33484a" stroke="#7e8b79" stroke-width="3"/><path d="M475 47L574 5 676 47Z" fill="#293e42"/><path d="M12 276Q97 190 277 228L347 277 311 312H74Z" fill="#765b3c" stroke="#bda16f" stroke-width="4"/><path d="M80 218V280M117 214V283M151 215V285M186 218V287M224 227V287" stroke="#b5a077" stroke-width="10"/><circle cx="550" cy="73" r="10" fill="#e6b970"/><path d="M310 186L221 249M341 173L239 244" stroke="#d1c4a1" stroke-width="2" stroke-dasharray="5 13" v-if="context.hadArrows"/></svg>
   <button class="ship-task__sound is-arrow" :disabled="busy" @click="playClip('arrow_change')"><i></i><strong>{{playing==='arrow_change'?'正在听…':context.hadArrows?'重听箭声变化':'再听江面'}}</strong><small>船舷这一边</small></button>
   <button class="ship-task__sound is-shore" :disabled="busy" @click="playClip('shore_report')"><i></i><strong>{{playing==='shore_report'?'正在听…':'重听岸上动静'}}</strong><small>远处寨楼</small></button>
  </template>
 </div>
 <div class="ship-task__speech" role="status" aria-live="polite"><span>{{task==='passage'?'韩伯':task==='side'?'韩伯':'阿成'}}</span><p>{{notice||(task==='passage'?'这捆散草横在路上，我过不去。挪到右舷边吧。':task==='side'?'该把哪一侧朝向曹营？先在船上指给我看。':(context.hadArrows?'箭声停了，岸上还有动静。你最担心哪一件事？':'岸上还没放箭，江面却有动静。你最担心哪一件事？'))}}</p></div>
 <template v-if="task==='listening'"><p v-if="soundError" class="ship-task__audio-error" role="alert">{{soundError}}</p><details class="ship-task__sound-text"><summary>听不清？看看刚才的动静</summary><div v-for="clip in clips" :key="clip"><p>{{clipCaption(clip,context)}}</p><button :disabled="busy" @click="readClip(clip)">我已读这段文字</button><small>{{state.heard.filter(h=>h.clip_id===clip).length?'已保留本次查看方式':''}}</small></div></details><details v-if="conflictText" class="ship-task__sound-text"><summary>本机还保留着另一句话</summary><blockquote>{{conflictText}}</blockquote><button v-if="context.initialPayload?.status!=='complete'" :disabled="busy" @click="recoverText">放回输入框</button></details><label class="ship-task__response">低声告诉同伴，你现在最担心什么<textarea :value="state.response" :disabled="busy" rows="2" maxlength="2000" @input="editResponse" @change="progress" placeholder="一句话也可以。"></textarea></label></template>
 <footer><button v-if="task==='passage'&&!state.walked" class="ship-task__primary" :disabled="busy||walking||state.obstacle==='passage'" @click="walk">{{walking?'韩伯正在通过…':'请韩伯从这里走过'}}</button><button v-else class="ship-task__primary" :disabled="!canFinish" @click="finish">{{task==='passage'?'通道留好了，回去系绳':task==='side'?'照这一侧，握住船舵':'把这句话告诉同伴'}}</button><button v-if="task==='side'" class="ship-task__quiet" :disabled="busy" @click="ask">请韩伯指一下</button><span v-if="task==='passage'">可拖散草到舷边，也可先点散草，再点束草位。</span><span v-else-if="task==='side'">再看看另一侧，想好了就握舵。</span></footer>
 </div>
</section>
</template>

<style scoped>
.ship-task{position:fixed;inset:0;z-index:75;background:#030d17c9;backdrop-filter:blur(7px);display:grid;place-items:center;padding:20px;color:#e8ddc3;font:15px/1.7 'Microsoft YaHei',sans-serif;overflow:auto}.ship-task *{box-sizing:border-box}.ship-task__frame{position:relative;width:min(960px,100%);max-height:95vh;overflow:auto;background:linear-gradient(135deg,#152a30f5,#08191ff7);border:1px solid #bca27170;box-shadow:0 24px 90px #0008;padding:24px 34px}.ship-task header{display:flex;align-items:center;justify-content:space-between;gap:18px}.ship-task header span{font-size:12px;letter-spacing:.2em;color:#bdb69e}.ship-task h2{font:30px/1.4 'STKaiti','KaiTi','SimSun',serif;margin:7px 0 0;letter-spacing:.1em}.ship-task button{font:inherit;color:inherit;cursor:pointer;border:1px solid #c3ab7466;background:#152b30;min-height:44px;padding:8px 15px}.ship-task button:disabled{opacity:.4;cursor:default}.ship-task button:focus-visible,.ship-task summary:focus-visible,.ship-task textarea:focus-visible{outline:2px solid #f4d795;outline-offset:4px}.ship-task__close{font-size:27px!important;border:0!important;background:transparent!important;width:44px;padding:0!important}.ship-task__instruction{font-size:14px;color:#c8c9b8;margin:15px 0}.ship-task__object-space{position:relative;aspect-ratio:760/340;max-height:330px;background:radial-gradient(ellipse,#3c505044,transparent 70%);border-block:1px solid #968d6d33}.ship-task__deck,.ship-task__water{display:block;width:100%;height:100%}.ship-task__hanber{position:absolute;left:13%;top:31%;width:70px;height:110px;background-size:400% 100%;background-position:0 50%;background-repeat:no-repeat;filter:drop-shadow(0 8px 4px #0006);transition:transform 1.6s linear;z-index:2;pointer-events:none}.ship-task__hanber.is-crossing{transform:translateX(min(53vw,570px))}.ship-task__bundle{position:absolute;left:42%;top:37%;width:18%;height:28%;padding:0!important;background:#958052!important;border:2px solid #d8bd7a!important;transform:rotate(-10d